    fontFamily: 'monospace',
    fontSize: '11px',
    fontWeight: 'bold',
    cursor: 'pointer',
    padding: '0 10px',
    pointerEvents: 'auto',
  });
  action.onclick = () => {
    window.dispatchEvent(new CustomEvent('ui:requestStairTraverse', {
      detail: { stairId: detail?.stairId, direction: dir }
    }));
    tip.style.display = 'none';
  };
  tip.appendChild(action);
}

